on_9a01dd5894ff6684" AS revoked WHERE revoked."breg_f_tenure_right_consent_decision_subject_d8cf00dce7c1d74e" = given."breg_f_tenure_right_consent_decision_subject_d8cf00dce7c1d74e" AND revoked."breg_f_tenure_right_consent_decision_recipient_013a7cb57170bba1" = given."breg_f_tenure_right_consent_decision_recipient_013a7cb57170bba1" AND revoked."breg_f_tenure_right_consent_decision_purpose_c081de5183ded0f1" = given."breg_f_tenure_right_consent_decision_purpose_c081de5183ded0f1" AND revoked."breg_f_tenure_right_consent_decision_scope_32d178e8bf55950b" = given."breg_f_tenure_right_consent_decision_scope_32d178e8bf55950b" AND revoked."breg_f_tenure_right_consent_decision_decision_8a2af2fa5fbefe4a" IN (''invalidated'', ''refused'', ''withdrawn'') AND revoked.record_lifecycle = ''active'' AND LEAST(revoked."breg_f_tenure_right_consent_decision_effective_5d7fbcc9f29d6285", revoked.created_at) >= LEAST(given."breg_f_tenure_right_consent_decision_effective_5d7fbcc9f29d6285", given.created_at)); PERFORM set_config(''registry.consent_probe'', COALESCE(prior_marker, ''''), true); RETURN; EXCEPTION WHEN OTHERS THEN RAISE; END';
